vector<int> morris(TreeNode* root){
    vector<int> out;
    TreeNode* cur = root;
    while (cur) {
        if (!cur->left) { out.push_back(cur->val); cur = cur->right; }
        else {
            TreeNode* pred = cur->left;
            while (pred->right && pred->right != cur) pred = pred->right;
            if (!pred->right) { pred->right = cur; cur = cur->left; }   // thread
            else { pred->right = nullptr; out.push_back(cur->val); cur = cur->right; } // unlink
        }
    }
    return out;
}

// up[0]=parent; up[k][v]=up[k-1][up[k-1][v]]
// LCA(a,b): lift deeper to same depth, then both jump while up[k]!=equal
int lca(int a, int b){
    if (dep[a] < dep[b]) swap(a, b);
    a = kthAncestor(a, dep[a] - dep[b]);
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
    return up[0][a];
}
